// ---- DOM refs ----
const timeline=document.getElementById('timeline');
const lcProgEl=document.getElementById('lcProgress');
const btnPrev=document.getElementById('btnPrev');
const btnNext=document.getElementById('btnNext');
const wfRow1El=document.getElementById('wfRow1');
const wfRow2El=document.getElementById('wfRow2');
const pipelineEl=document.getElementById('pipelineContainer');
const wfRowsEl=document.getElementById('wfRowsContainer');
let activeScenario=0, lcCurrent=-1, lcTotal=0;

function setScenario(idx){
  activeScenario=idx; lcCurrent=-1;
  const page2=document.getElementById('page2');
  const wasIntro=page2.classList.contains('intro');
  if(wasIntro){
    page2.classList.remove('intro');
    document.querySelector('#page2 header').style.marginTop='';
    document.getElementById('lcControls').classList.add('visible');
    // Animate scenario box and lc-stage in
    const scBox=document.getElementById('scenarioBox');
    const lcStage=document.querySelector('.lc-stage');
    [scBox,lcStage].forEach((el,i)=>{
      el.style.opacity='0';
      el.style.transform='translateY(24px)';
      el.style.transition='none';
      requestAnimationFrame(()=>{requestAnimationFrame(()=>{
        el.style.transition='opacity .5s ease '+(i*.15)+'s, transform .5s cubic-bezier(.4,0,.2,1) '+(i*.15)+'s';
        el.style.opacity='1';
        el.style.transform='translateY(0)';
      });});
    });
  }
  const sc=SCENARIOS[idx];
  document.querySelectorAll('.sc-btn').forEach((b,i)=>b.classList.toggle('active',i===idx));
  document.getElementById('scBoxIcon').innerHTML='<img src="'+sc.icon+'" style="width:36px;height:36px;">';
  document.getElementById('scBoxTitle').textContent=sc.title;
  document.getElementById('scBoxDesc').textContent=sc.desc;
  document.getElementById('scBoxRoles').innerHTML=sc.badges.map(b=>`<div class="sr" style="background:${b.bg};color:${b.color};">${b.text}</div>`).join('');

  const r1=sc.row1;
  document.getElementById('wfRow1Label').innerHTML=r1.label;
  setCol('colLeft',r1.left); setCol('colRight',r1.right);
  document.querySelector('#wfArrow1 svg').innerHTML=r1.oneWay?makeOneWayArrowSvg(r1.arrowColor):makeArrowSvg(r1.arrowColor);

  if(sc.row2){
    const r2=sc.row2;
    document.getElementById('wfRow2Label').innerHTML=r2.label;
    setCol('colLeft2',r2.left); setCol('colRight2',r2.right);
    document.querySelector('#wfArrow2 svg').innerHTML=makeArrowSvg(r2.arrowColor);
  }
  wfRow2El.classList.remove('visible');

  // Toggle pipeline vs normal rows
  if(sc.pipeline){
    wfRowsEl.style.display='none';
    pipelineEl.classList.add('visible');
    // Reset pipe boxes
    document.querySelectorAll('.pipe-box').forEach(b=>{b.classList.remove('active','done');b.style.borderColor='';});
    document.querySelector('.pipeline').classList.remove('highlight');
  } else {
    wfRowsEl.style.display='';
    pipelineEl.classList.remove('visible');
  }

  timeline.innerHTML='';
  sc.steps.forEach((s,i)=>{
    const div=document.createElement('div');
    div.className='step'; div.dataset.role=s.role; div.id='step'+i;
    let taskHtml='';
    if(s.task){
      let arrowHtml='';
      if(s.task.arrow){const a=s.task.arrow; arrowHtml=`<div class="task-arrow"><div class="ta-from" style="background:${a.fromBg};color:${a.fromColor};">${a.from}</div><svg viewBox="0 0 20 10"><polygon points="14,5 8,1 8,9" fill="${a.fillColor}"/><rect x="2" y="4" width="8" height="2" rx="1" fill="${a.fillColor}" opacity=".5"/></svg><div class="ta-to" style="background:${a.toBg};color:${a.toColor};">${a.to}</div></div>`;}
      taskHtml=`<div class="task-preview"><div class="task-status" style="background:${s.task.statusBg};color:${s.task.statusColor};">${s.task.status}</div><div class="task-info"><div class="ti-title">${s.task.title}</div><div class="ti-meta">${s.task.meta}</div></div>${arrowHtml}</div>`;
    }
    div.innerHTML=`<div class="step-dot"></div><div class="step-card"><div class="step-header"><div class="step-num" style="background:${s.numBg};color:${s.numColor};">${s.num}</div><div class="step-title">${s.title}</div></div><div class="step-body">${s.body}</div>${taskHtml}</div>`;
    timeline.appendChild(div);
  });
  if(sc.disclaimer){
    const ddiv=document.createElement('div');
    ddiv.className='scenario-disclaimer';
    ddiv.innerHTML=sc.disclaimer;
    timeline.appendChild(ddiv);
  }
  lcTotal=sc.steps.length;
  lcProgEl.innerHTML='';
  for(let i=0;i<lcTotal;i++){const d=document.createElement('div');d.className='prog-dot';lcProgEl.appendChild(d);}
  lcUpdate();
  window.scrollTo({top:0,behavior:'smooth'});
}

function setCol(prefix,data){
  if(data.isImg){document.getElementById(prefix+'Av').innerHTML='<img src="'+data.emoji+'" style="width:28px;height:28px;">';}else{document.getElementById(prefix+'Av').textContent=data.emoji;}
  document.getElementById(prefix+'Av').style.background=data.bg;
  document.getElementById(prefix+'Av').style.borderColor=data.border;
  document.getElementById(prefix+'Name').textContent=data.name;
  document.getElementById(prefix+'Role').textContent=data.role;
}
function makeArrowSvg(c){return `<polygon points="0,7 8,1 8,5" fill="${c}"/><rect x="8" y="5.5" width="64" height="3" rx="1" fill="${c}" opacity=".3"/><polygon points="80,7 72,1 72,13" fill="${c}"/><polygon points="0,7 8,13 8,9" fill="${c}"/>`;}
function makeOneWayArrowSvg(c){return `<rect x="2" y="5.5" width="70" height="3" rx="1" fill="${c}" opacity=".3"/><polygon points="80,7 72,1 72,13" fill="${c}"/>`;}
function getColEl(k){const m={left:'colLeft',right:'colRight',left2:'colLeft2',right2:'colRight2'};return document.getElementById(m[k]);}
function highlightRow(el,on){el.style.borderColor=on?'var(--dalux)':'var(--border)';el.style.boxShadow=on?'0 2px 12px rgba(141,198,63,.12)':'0 1px 3px rgba(0,0,0,.06)';}

function lcUpdate(){
  const sc=SCENARIOS[activeScenario];
  const steps=document.querySelectorAll('.step');
  const ctrlEl=document.getElementById('lcControls');
  steps.forEach((s,i)=>{s.classList.remove('active','done');if(i<lcCurrent)s.classList.add('done');else if(i===lcCurrent)s.classList.add('active');});
  lcProgEl.querySelectorAll('.prog-dot').forEach((d,i)=>{d.classList.remove('filled','current');if(i<lcCurrent)d.classList.add('filled');else if(i===lcCurrent)d.classList.add('current');});

  if(sc.row2) wfRow2El.classList.toggle('visible',lcCurrent>=sc.row2.showAtStep);

  // Pipeline highlighting
  if(sc.pipeline){
    const pipeBoxes=[0,1,2,3].map(i=>document.getElementById('pipe'+i));
    const pipeEl=document.querySelector('.pipeline');
    pipeBoxes.forEach(b=>{if(b){b.classList.remove('active','done');b.style.borderColor='';}});
    pipeEl.classList.toggle('highlight',lcCurrent>=0);
    if(lcCurrent>=0){
      const step=sc.steps[lcCurrent];
      const colors=['var(--accent)','var(--yellow)','var(--purple)','var(--orange)'];
      // Mark previous pipes as done
      for(let i=0;i<lcCurrent;i++){
        const ps=sc.steps[i];
        if(ps.pipe!==undefined&&pipeBoxes[ps.pipe]){pipeBoxes[ps.pipe].classList.add('done');pipeBoxes[ps.pipe].style.borderColor=colors[ps.pipe];}
      }
      // Mark current pipe as active
      if(step.pipe!==undefined&&pipeBoxes[step.pipe]){
        pipeBoxes[step.pipe].classList.remove('done');
        pipeBoxes[step.pipe].classList.add('active');
        pipeBoxes[step.pipe].style.borderColor=colors[step.pipe];
      }
      // On done step, highlight godkjenning branch
      if(step.col==='done'){
        pipeBoxes.forEach((b,i)=>{if(b){b.classList.add('done');b.style.borderColor=colors[i]||'var(--green)';}});
        if(pipeBoxes[2]){pipeBoxes[2].style.borderColor='var(--green)';}
      }
    }
  }
  const avs=['colLeft','colRight','colLeft2','colRight2'].map(id=>document.getElementById(id+'Av'));

  // Remove pulse from all
  avs.forEach(a=>{a.classList.remove('pulse');a.style.transform='';});

  if(lcCurrent>=0){
    ctrlEl.classList.add('visible');
    const step=sc.steps[lcCurrent];
    if(!sc.pipeline){
    highlightRow(wfRow1El,step.row===1||step.col==='done');
    if(sc.row2) highlightRow(wfRow2El,(step.row===2||step.col==='done')&&wfRow2El.classList.contains('visible'));

    // Apply role overrides
    const roleMap={left:'colLeft',right:'colRight',left2:'colLeft2',right2:'colRight2'};
    // Reset to defaults
    if(sc.row1){document.getElementById('colLeftRole').textContent=sc.row1.left.role;document.getElementById('colRightRole').textContent=sc.row1.right.role;setCol('colLeft',sc.row1.left);setCol('colRight',sc.row1.right);}
    if(sc.row2){document.getElementById('colLeft2Role').textContent=sc.row2.left.role;document.getElementById('colRight2Role').textContent=sc.row2.right.role;}
    // Apply column overrides for this step (swap columns dynamically)
    if(step.colOverride){
      Object.entries(step.colOverride).forEach(([k,v])=>{setCol(k,v);});
    }
    if(step.labelOverride){document.getElementById('wfRow1Label').innerHTML=step.labelOverride;}
    // Apply overrides for this step
    if(step.roleOverride){Object.entries(step.roleOverride).forEach(([k,v])=>{document.getElementById(roleMap[k]+'Role').textContent=v;});}

    if(step.col==='done'){
      avs.forEach(a=>{a.style.borderColor='var(--green)';});
    } else {
      if(sc.row1){document.getElementById('colLeftAv').style.borderColor=sc.row1.left.border;document.getElementById('colRightAv').style.borderColor=sc.row1.right.border;}
      if(sc.row2){document.getElementById('colLeft2Av').style.borderColor=sc.row2.left.border;document.getElementById('colRight2Av').style.borderColor=sc.row2.right.border;}
      const ae=getColEl(step.col);if(ae){const av=ae.querySelector('.col-avatar');av.classList.add('pulse');av.style.transform='scale(1.2)';}
    }
    } // end !sc.pipeline
  } else {
    highlightRow(wfRow1El,false); highlightRow(wfRow2El,false);
    if(sc.row1){document.getElementById('colLeftAv').style.borderColor=sc.row1.left.border;document.getElementById('colRightAv').style.borderColor=sc.row1.right.border;document.getElementById('colLeftRole').textContent=sc.row1.left.role;document.getElementById('colRightRole').textContent=sc.row1.right.role;setCol('colLeft',sc.row1.left);setCol('colRight',sc.row1.right);document.getElementById('wfRow1Label').innerHTML=sc.row1.label;}
    if(sc.row2){document.getElementById('colLeft2Av').style.borderColor=sc.row2.left.border;document.getElementById('colRight2Av').style.borderColor=sc.row2.right.border;document.getElementById('colLeft2Role').textContent=sc.row2.left.role;document.getElementById('colRight2Role').textContent=sc.row2.right.role;}
  }
  btnPrev.disabled=lcCurrent<=0;
  btnNext.disabled=false;
  btnNext.textContent=lcCurrent<0?'Start ▶':lcCurrent>=lcTotal-1?'↑ Til toppen':'Neste steg →';
  if(lcCurrent>=lcTotal-1)btnNext.classList.remove('primary');else btnNext.classList.add('primary');
  if(lcCurrent>=0)steps[lcCurrent]?.scrollIntoView({behavior:'smooth',block:'center'});
}

function lcNext(){if(lcCurrent>=lcTotal-1){lcCurrent=-1;lcUpdate();window.scrollTo({top:0,behavior:'smooth'});}else{lcCurrent++;lcUpdate();}}
function lcPrev(){if(lcCurrent>0){lcCurrent--;lcUpdate();}}
function lcReset(){lcCurrent=-1;lcUpdate();window.scrollTo({top:0,behavior:'smooth'});}
setScenario(0);
document.getElementById('page2').classList.add('intro');
document.getElementById('lcControls').classList.remove('visible');
document.querySelectorAll('.sc-btn').forEach(b=>b.classList.remove('active'));
